    def loss_fn(self, params, x, y):
        if self.model_data["normalized"]:
            y_out = self.model.apply(params, x)
            y_out = self.normalizer_y.decode(y_out)
            x_real = self.normalizer_x.decode(x)
        else:
            y_out = self.model.apply(params, x)
            x_real = x

        if self.type == 'mooneyrivlin':
            loss_int = self.mooneyRivlinLossInt(y_out)
        elif self.type == 'neohookean':
            loss_int = self.neoHookeanLossInt(y_out)
        elif self.type == 'arrudaboyce':
            loss_int = self.arrudaBoyceLossInt(y_out)
        else:
            raise ValueError(f"Unsupported energy type for B2VinoLoss: {self.type}")

        # calculate the boundary loss (internal pressure on r = R_in) -- same as B2Loss
        disp_x, disp_y = y_out[..., 0:1], y_out[..., 1:2]
        u_x_inner = disp_x[:, :, 0, :]
        u_y_inner = disp_y[:, :, 0, :]
        dtheta = (jnp.pi / 2.0) / self.num_y
        theta_row = jnp.linspace(0, 1, self.num_y) * (jnp.pi / 2.0)
        theta_col = theta_row[None, :, None]
        u_r_inner = u_x_inner * jnp.cos(theta_col) + u_y_inner * jnp.sin(theta_col)
        pressure = x_real[:, :, 0, :]
        loss_bnd = jnp.sum(u_r_inner * pressure) * self.R_in * dtheta

        return jnp.where(loss_int - loss_bnd > 1e6, 1e6, loss_int - loss_bnd)
